#!/usr/bin/env bash
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
cd "$REPO_ROOT"

mkdir -p app/src/main/java/com/wayars/app/presentation/ui/screen/terms

write_file() {
  local path="$1"
  local b64="$2"
  mkdir -p "$(dirname "$path")"
  printf "%s" "$b64" | base64 -d > "$path"
  echo "OK: wrote $path"
}

B64_0=""
write_file "app/src/main/java/com/wayars/app/WayArsApplication.kt" "$B64_0"

B64_1=""
write_file "app/src/main/java/com/wayars/app/data/prefs/SettingsDataStore.kt" "$B64_1"

B64_2=""
write_file "app/src/main/java/com/wayars/app/domain/repository/SettingsRepository.kt" "$B64_2"

B64_3=""
write_file "app/src/main/java/com/wayars/app/data/repository/SettingsRepositoryImpl.kt" "$B64_3"

B64_4=""
write_file "app/src/main/java/com/wayars/app/presentation/MainViewModel.kt" "$B64_4"

B64_5=""
write_file "app/src/main/java/com/wayars/app/presentation/ui/screen/terms/TermsGateScreen.kt" "$B64_5"

B64_6=""
write_file "app/src/main/java/com/wayars/app/presentation/ui/screen/settings/SettingsScreen.kt" "$B64_6"

B64_7=""
write_file "app/src/main/java/com/wayars/app/presentation/ui/navigation/WayArsNavHost.kt" "$B64_7"

B64_8=""
write_file "app/src/main/java/com/wayars/app/presentation/ui/navigation/MainScreen.kt" "$B64_8"

B64_9=""
write_file "app/src/main/res/values/strings.xml" "$B64_9"

B64_10=""
write_file "app/src/main/res/values-ru/strings.xml" "$B64_10"

B64_11=""
write_file "app/src/main/res/values-pl/strings.xml" "$B64_11"

B64_12=""
write_file "app/src/main/res/values-de/strings.xml" "$B64_12"

B64_13=""
write_file "app/src/main/res/values-fr/strings.xml" "$B64_13"

B64_14=""
write_file "app/src/main/res/values-ro/strings.xml" "$B64_14"

B64_15=""
write_file "app/src/main/res/values-uk/strings.xml" "$B64_15"

echo "Done. Rebuild the app to verify."
